begin;

create table public."Dim_Jornal" (
  "Id_Jornal" bigint generated by default as identity primary key,
  "id_Tipo_Jornal" smallint not null references public."Dim_TipoJornal" ("Id_Tipo_Jornal") on update cascade on delete restrict,
  "Inicio" date not null,
  "Fin" date not null,
  "Importe_Soles" numeric(12,2),
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ck_dim_jornal_vigencia check ("Fin" >= "Inicio"),
  constraint ck_dim_jornal_importe_no_negativo check ("Importe_Soles" is null or "Importe_Soles" >= 0),
  constraint uq_dim_jornal_tipo_vigencia unique ("id_Tipo_Jornal", "Inicio", "Fin")
);

comment on table public."Dim_Jornal" is
  'Importes monetarios por tipo de jornal y periodo de vigencia, expresados en soles.';
comment on column public."Dim_Jornal"."Importe_Soles" is
  'Importe del jornal en soles. NULL indica que no se proporciono un monto.';
comment on column public."Dim_Jornal".estado is
  'Estado del registro: 1 activo, 0 inactivo.';

create index idx_dim_jornal_tipo_periodo
  on public."Dim_Jornal" ("id_Tipo_Jornal", "Inicio", "Fin");

alter table public."Dim_Jornal" enable row level security;
revoke all on table public."Dim_Jornal" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_Jornal" to authenticated;

create policy dim_jornal_select_admin on public."Dim_Jornal"
for select to authenticated using ((select private.is_admin()));
create policy dim_jornal_insert_admin on public."Dim_Jornal"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_jornal_update_admin on public."Dim_Jornal"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_jornal_delete_admin on public."Dim_Jornal"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_jornal_updated_at()
returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_jornal_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_jornal_updated_at
before update on public."Dim_Jornal"
for each row execute function private.set_dim_jornal_updated_at();

